using System;using System.IO;using System.Diagnostics;using System.Security.Principal;using Microsoft.Win32;using System.Web.Script.Serialization;
internal static class EnergySaverPolicyProbe {
 const string Key=@"SOFTWARE\Policies\Microsoft\Power\EnergySaver",Value="EnableEnergySaver";
 public static int Main(string[] args){if(args.Length==2&&args[0]=="--elevate"){try{var p=Process.Start(new ProcessStartInfo(typeof(EnergySaverPolicyProbe).Assembly.Location,"--probe \""+Path.GetFullPath(args[1])+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden});p.WaitForExit();return p.ExitCode;}catch{return 1;}}
 if(args.Length!=2||args[0]!="--probe"||!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 77;
 bool before=EnergySaverLease.ActiveSaver,created=false,on=false,restored=false;string error=null;try{using(var prior=Registry.LocalMachine.OpenSubKey(Key)){if(prior!=null&&prior.GetValue(Value)!=null)throw new IOException("Existing administrator policy: no overwrite");}using(var k=Registry.LocalMachine.CreateSubKey(Key)){k.SetValue(Value,1,RegistryValueKind.DWord);created=true;}EnergySaverLease.Refresh();for(int n=0;n<20;n++){System.Threading.Thread.Sleep(500);if(EnergySaverLease.ActiveSaver){on=true;break;}}}catch(Exception e){error=e.Message;}finally{if(created){using(var k=Registry.LocalMachine.OpenSubKey(Key,true)){if(k!=null&&Convert.ToString(k.GetValue(Value))=="1")k.DeleteValue(Value,false);}EnergySaverLease.Refresh();System.Threading.Thread.Sleep(1500);restored=EnergySaverLease.ActiveSaver==before;}}File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Before=before,EnabledObserved=on,After=EnergySaverLease.ActiveSaver,Restored=restored,Error=error,Scope="Only Power/EnergySaver/EnableEnergySaver; no global policy refresh"}));return on&&restored&&error==null?0:1;}
}
